          then assign component_beep_remainder := component_beep_remainder - 48000;
        }
        then if component_beep_remainder >= 24000 {
          first start;
          then assign component_beep_remainder := component_beep_remainder - 24000;
        }
        then if component_beep_remainder >= 12000 {
          first start;
          then assign component_beep_remainder := component_beep_remainder - 12000;
        }
        then if component_beep_remainder >= 6000 {
          first start;
          then assign component_beep_remainder := component_beep_remainder - 6000;
        }
        then if component_beep_remainder >= 3000 {
          first start;
          then assign component_beep_remainder := component_beep_remainder - 3000;
        }
        then if component_beep_remainder >= 3000 - component_beep_phase {
          first start;
          then assign component_beep_phase := component_beep_remainder - (3000 - component_beep_phase);
        } else {
          first start;
          then assign component_beep_phase := component_beep_phase + component_beep_remainder;
        }
      }
      then assign component_beep_value := (component_run_value) and component_beep_started and component_beep_phase < 100;
      then assign component_beep_enabled := component_run_value;
    }
    out attribute buzzerToneHz : Integer = (if component_beep_value ? 1000 else 0);
  }
  part system : Controller;
}
